<script setup>
import { computed, onMounted, onUnmounted, ref, watch } from 'vue';
import { api, getToken, setToken } from './api.js';
import { currentState, filterDevices, formatTime, statusLabels, templateSnapshot, validateStates } from './model.js';
const authenticated=ref(false),starting=ref(true),username=ref('admin'),loginPassword=ref(''),loginError=ref(''),loginBusy=ref(false);
const page=ref('overview'),query=ref(''),connectionFilter=ref('all'),view=ref('cards'),pageNo=ref(1),pageSize=12;
const devices=ref([]),templates=ref([]),logs=ref([]),selected=ref(new Set()),loadError=ref(''),lastRefresh=ref(0),loading=ref(false);
const modal=ref(''),modalError=ref(''),busy=ref(false),toast=ref(''),draft=ref(null),activeDevice=ref(null),templateId=ref(''),targetIds=ref([]),afterState=ref(''),batchResults=ref([]),formElement=ref(null);
const oldPassword=ref(''),newPassword=ref(''),confirmPassword=ref(''),passwordError=ref('');const enrollmentKey=ref(''),newEnrollmentKey=ref(''),keyError=ref(''),keyBusy=ref(false);let pollTimer,toastTimer,refreshing=false;
const desktopBridge=typeof window.roomDesktop?.info==='function'?window.roomDesktop:null;
const desktopInfo=ref(null),desktopError=ref(''),backupBusy=ref(false),backupPath=ref('');
const desktopAddresses=computed(()=>(desktopInfo.value?.addresses||[]).map(address=>/^https?:\/\//i.test(address)?address:`http://${address.includes(':')?'['+address+']':address}:${desktopInfo.value.port}`).filter(Boolean));
const clone=value=>JSON.parse(JSON.stringify(value));
const uniqueId=()=>globalThis.crypto?.randomUUID?.()||'state-'+Date.now().toString(36)+'-'+Array.from(crypto.getRandomValues(new Uint32Array(2))).map(n=>n.toString(36)).join('');
const icons=['✓','◷','−','◇','!','○'];
const nav=[{id:'overview',icon:'▦',name:'房间总览',desc:'每个房间的状态，都有清晰的反馈。'},{id:'devices',icon:'▤',name:'设备管理',desc:'维护房间资料与设备连接，支持搜索、筛选和分页。'},{id:'templates',icon:'◇',name:'状态模板',desc:'统一维护状态选项，按需下发到选定设备。'},{id:'logs',icon:'≡',name:'操作记录',desc:'以设备确认结果为准，追踪每一次远程操作。'},{id:'settings',icon:'⚙',name:'系统设置',desc:'管理账户与设备接入信息。'}];
const currentPage=computed(()=>nav.find(n=>n.id===page.value));
const filtered=computed(()=>filterDevices(devices.value,query.value,connectionFilter.value));
const pageCount=computed(()=>Math.max(1,Math.ceil(filtered.value.length/pageSize)));
const visibleDevices=computed(()=>filtered.value.slice((pageNo.value-1)*pageSize,pageNo.value*pageSize));
const onlineCount=computed(()=>devices.value.filter(d=>d.online).length);
const pendingCount=computed(()=>devices.value.filter(d=>d.pending).length);
const allOnPage=computed(()=>visibleDevices.value.length>0&&visibleDevices.value.every(d=>selected.value.has(d.deviceId)));
const chosenTemplate=computed(()=>templates.value.find(t=>t.id===templateId.value));
const modalTargets=computed(()=>devices.value.filter(d=>targetIds.value.includes(d.deviceId)));
const usable=(d)=>d.online&&!d.pending&&!!d.snapshot&&!loadError.value;
const connectionOrigin=location.origin;
watch([query,connectionFilter],()=>pageNo.value=1);
watch(pageCount,n=>pageNo.value=Math.min(pageNo.value,n));
watch(templateId,()=>{afterState.value=chosenTemplate.value?.states?.[0]?.id||''});
watch(page,p=>{if(p==='settings'&&authenticated.value)loadEnrollmentKey()});
function notify(message){toast.value=message;clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.value='',4500)}
function navigate(id){page.value=id;pageNo.value=1}
function closeModal(){if(!busy.value){modal.value='';modalError.value='';draft.value=null}}
function openModal(type){modalError.value='';batchResults.value=[];modal.value=type}
function toggleSelection(id,checked){const next=new Set(selected.value);checked?next.add(id):next.delete(id);selected.value=next}
function selectPage(checked){const next=new Set(selected.value);visibleDevices.value.forEach(d=>checked?next.add(d.deviceId):next.delete(d.deviceId));selected.value=next}
function expireSession(){authenticated.value=false;devices.value=[];templates.value=[];logs.value=[];modal.value='';selected.value=new Set();enrollmentKey.value='';newEnrollmentKey.value='';loginError.value='登录已过期，请重新登录。'}
async function refresh(){if(!authenticated.value||refreshing||backupBusy.value)return;refreshing=true;loading.value=true;const requestToken=getToken();try{const result=await Promise.all([api('/admin/devices'),api('/admin/templates'),api('/admin/logs')]);if(authenticated.value&&getToken()===requestToken){devices.value=result[0];templates.value=result[1];logs.value=result[2];lastRefresh.value=Date.now();loadError.value=''}}catch(error){if(authenticated.value)loadError.value=error.message}finally{refreshing=false;loading.value=false}}
async function login(){loginBusy.value=true;loginError.value='';try{const response=await api('/auth/login',{method:'POST',body:{username:username.value.trim(),password:loginPassword.value}});setToken(response.token);authenticated.value=true;loginPassword.value='';await refresh()}catch(error){loginError.value=error.message}finally{loginBusy.value=false}}
async function logout(){try{await api('/auth/logout',{method:'POST'})}catch{/* The local session must still be removed when disconnected. */}setToken('');authenticated.value=false;modal.value='';devices.value=[];templates.value=[];logs.value=[];selected.value=new Set();enrollmentKey.value='';newEnrollmentKey.value='';loginError.value=''}
async function command(device,snapshot){if(!usable(device))throw new Error('设备离线、等待确认或管理电脑连接中断，请稍后重试');return api('/admin/devices/'+encodeURIComponent(device.deviceId)+'/commands',{method:'POST',body:{baseRevision:device.revision,snapshot}})}
function openSwitch(device){activeDevice.value=clone(device);openModal('switch')}
async function changeState(stateId){if(stateId===activeDevice.value.snapshot.current)return;busy.value=true;modalError.value='';try{const snapshot=clone(activeDevice.value.snapshot);snapshot.current=stateId;await command(activeDevice.value,snapshot);modal.value='';notify('指令已提交，等待设备确认');await refresh()}catch(error){modalError.value=error.message;await refresh()}finally{busy.value=false}}
function editDevice(device){activeDevice.value=clone(device);draft.value=clone(device.snapshot);openModal('device')}
async function saveDevice(){busy.value=true;modalError.value='';try{const snapshot=clone(draft.value);snapshot.number=snapshot.number.trim();snapshot.name=snapshot.name.trim();if(!snapshot.number||!snapshot.name)throw new Error('房间号和名称不能为空');await command(activeDevice.value,snapshot);modal.value='';notify('资料已提交，等待设备确认');await refresh()}catch(error){modalError.value=error.message;await refresh()}finally{busy.value=false}}
function newState(){return {id:uniqueId(),name:'',color:'#83dfc2',icon:'✓'}}
function editTemplate(template){draft.value=template?clone(template):{name:'',states:[newState()]};openModal('template')}
function removeState(index){if(draft.value.states.length===1){modalError.value='至少保留一个状态';return}draft.value.states.splice(index,1)}
async function saveTemplate(){busy.value=true;modalError.value='';try{const value=clone(draft.value);value.name=value.name.trim();value.states=value.states.map(s=>({...s,name:s.name.trim()}));if(!value.name)throw new Error('请输入模板名称');const error=validateStates(value.states);if(error)throw new Error(error);await api('/admin/templates',{method:'POST',body:value});modal.value='';notify('模板已保存，尚未下发设备');await refresh()}catch(error){modalError.value=error.message}finally{busy.value=false}}
function requestDelete(template){draft.value=clone(template);openModal('delete')}
async function deleteTemplate(){busy.value=true;try{await api('/admin/templates/'+encodeURIComponent(draft.value.id),{method:'DELETE'});modal.value='';notify('模板已删除，设备已有配置不受影响');await refresh()}catch(error){modalError.value=error.message}finally{busy.value=false}}
function openDeploy(template){if(!templates.value.length){notify('请先新建一个状态模板');navigate('templates');return}templateId.value=template?.id||templates.value[0].id;afterState.value=templates.value.find(t=>t.id===templateId.value)?.states?.[0]?.id||'';targetIds.value=template?[]:[...selected.value].filter(id=>devices.value.some(d=>d.deviceId===id&&usable(d)));openModal('deploy')}
function toggleTarget(id,checked){targetIds.value=checked?[...targetIds.value,id]:targetIds.value.filter(x=>x!==id)}
async function deploy(){modalError.value='';batchResults.value=[];if(!targetIds.value.length){modalError.value='请选择至少一台可操作的在线设备';return}if(!chosenTemplate.value){modalError.value='模板已被删除，请重新选择';return}busy.value=true;const template=clone(chosenTemplate.value),current=afterState.value;const targets=modalTargets.value.map(d=>clone(d));for(const device of targets){try{await command(device,templateSnapshot(device.snapshot,template.states,current));batchResults.value.push({id:device.deviceId,message:'已提交，等待设备确认',ok:true})}catch(error){batchResults.value.push({id:device.deviceId,message:error.message,ok:false})}}await refresh();busy.value=false;notify('批量提交完成，请查看各设备确认结果')}
async function changePassword(){passwordError.value='';if(newPassword.value!==confirmPassword.value){passwordError.value='两次输入的新密码不一致';return}busy.value=true;try{await api('/auth/password',{method:'POST',body:{oldPassword:oldPassword.value,newPassword:newPassword.value}});oldPassword.value=newPassword.value=confirmPassword.value='';await logout();notify('密码已修改，请使用新密码登录')}catch(error){passwordError.value=error.message}finally{busy.value=false}}
async function loadEnrollmentKey(){try{const r=await api('/admin/settings/enrollment-key');enrollmentKey.value=r.enrollmentKey||'';keyError.value=''}catch(error){keyError.value=error.message}}
async function changeEnrollmentKey(){keyError.value='';const value=newEnrollmentKey.value.trim();if(value.length<12||value.length>255){keyError.value='注册密钥至少12字符且不超过255字符';return}keyBusy.value=true;try{await api('/admin/settings/enrollment-key',{method:'POST',body:{enrollmentKey:value}});enrollmentKey.value=value;newEnrollmentKey.value='';notify('注册密钥已更新，之后注册的设备请使用新密钥')}catch(error){keyError.value=error.message}finally{keyBusy.value=false}}
function exportLogs(){const blob=new Blob([JSON.stringify(logs.value,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='房间状态-操作记录.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function loadDesktopInfo(){if(!desktopBridge)return;try{desktopInfo.value=await desktopBridge.info();desktopError.value=''}catch(error){desktopError.value=error.message||'无法读取本机信息'}}
async function openDataDirectory(){try{await desktopBridge.openData()}catch(error){desktopError.value=error.message||'无法打开数据目录'}}
async function backupData(){if(backupBusy.value)return;desktopError.value='';backupPath.value='';backupBusy.value=true;try{const result=await desktopBridge.backup();if(!result.cancelled){backupPath.value=result.path||'';setToken('');expireSession();loginError.value='备份已完成，通信服务已恢复，请重新登录。';notify('数据备份已完成，请重新登录')}}catch(error){desktopError.value=error.message||'备份未完成，请重试'}finally{backupBusy.value=false;await refresh()}}
function onKey(event){if(event.key==='Escape')closeModal()}
onMounted(async()=>{await loadDesktopInfo();window.addEventListener('room-auth-expired',expireSession);window.addEventListener('keydown',onKey);if(getToken()){try{const me=await api('/auth/me');username.value=me.username;authenticated.value=true;await refresh()}catch(error){setToken('');loginError.value=error.message}}starting.value=false;pollTimer=setInterval(refresh,2000)});
onUnmounted(()=>{clearInterval(pollTimer);clearTimeout(toastTimer);window.removeEventListener('room-auth-expired',expireSession);window.removeEventListener('keydown',onKey)});
</script>

<template>
 <div v-if="!authenticated" class="login-shell"><form class="login-card" @submit.prevent="login"><div class="login-brand">▥ 房间状态 · 电脑管理中心</div><h1>欢迎回来</h1><p class="muted">登录后查看设备，并管理房间状态。</p><label>管理员账户<input v-model="username" name="username" autocomplete="username" required maxlength="80"></label><label>登录密码<input v-model="loginPassword" name="password" type="password" autocomplete="current-password" required></label><p class="error" role="alert">{{ loginError }}</p><button class="primary" :disabled="loginBusy||starting">{{ starting?'正在检查会话…':loginBusy?'正在登录…':'登录管理中心' }}</button><p class="hint" style="margin-top:24px">账户为 admin，密码是首次启动管理程序时设置的管理密码。设备注册密钥不能用于管理员登录。</p></form></div>
 <template v-else>
 <aside><div class="logo"><span>▥</span>房间状态</div><div class="sublogo">电脑管理中心</div><nav><button v-for="item in nav" :key="item.id" :class="{active:page===item.id}" @click="navigate(item.id)"><i>{{ item.icon }}</i>{{ item.name }}</button></nav><div class="sidefoot"><strong>独立运行 · 集中管理</strong>设备断网后仍可本地操作<br>管理规模可随设备数量扩展</div></aside>
 <main><header class="topbar"><span>管理工作区 / {{ currentPage.name }}</span><div class="topbar-right"><small v-if="!loadError" class="activity">自动更新</small><span>{{ username }}</span><button class="flat" @click="logout">退出</button></div></header><div class="heading"><div><div class="eyebrow">空间运行概况</div><h1>{{ currentPage.name }}</h1><p class="muted">{{ currentPage.desc }}</p></div><button v-if="['overview','devices'].includes(page)" class="primary" @click="openModal('enroll')">＋ 接入设备</button></div>
 <div v-if="loadError" class="connection-banner" role="alert">本机通信服务连接异常：{{ loadError }}。以下为最近取得的数据，已暂停远程操作。<button class="flat" @click="refresh">重新连接</button></div>
 <template v-if="page==='overview'||page==='devices'">
 <div v-if="page==='overview'" class="metrics"><div class="metric">设备总数<b>{{ devices.length }}</b><small>支持持续接入设备</small></div><div class="metric">在线设备<b>{{ onlineCount }}</b><small>15 秒内收到心跳</small></div><div class="metric">离线设备<b>{{ devices.length-onlineCount }}</b><small>显示最后已知状态</small></div><div class="metric">等待确认<b>{{ pendingCount }}</b><small>尚未视为执行成功</small></div></div>
 <div class="tools"><input v-model="query" type="search" placeholder="搜索房间号、名称或设备编号" aria-label="搜索设备"><select v-model="connectionFilter" aria-label="连接状态"><option value="all">全部连接状态</option><option value="online">在线设备</option><option value="offline">离线设备</option></select><span class="spacer"></span><span class="muted">共 {{ filtered.length }} 台</span><button :class="{primary:view==='cards'&&page==='overview'}" @click="view='cards';navigate('overview')">▦ 卡片</button><button :class="{primary:view==='list'||page==='devices'}" @click="view='list'">☷ 列表</button></div>
 <div class="bulk"><label class="page-select"><input type="checkbox" :checked="allOnPage" :disabled="!visibleDevices.length" @change="selectPage($event.target.checked)">选择本页</label><span class="selected-count">已选 {{ selected.size }} 台</span><button :disabled="!selected.size||!!loadError" @click="openDeploy()">下发状态模板</button><button class="flat" @click="selected=new Set()">清空选择</button></div>
 <div v-if="!filtered.length" class="empty"><h3>{{ devices.length?'没有匹配的设备':'还没有设备接入' }}</h3><p>{{ devices.length?'请调整搜索词或连接状态筛选。':'在安卓端的“服务器地址”中填写管理电脑地址，并输入注册密钥，注册后自动出现在这里。' }}</p><button v-if="!devices.length" @click="openModal('enroll')">查看接入步骤</button></div>
 <div v-else-if="view==='cards'&&page==='overview'" class="grid"><article v-for="device in visibleDevices" :key="device.deviceId" class="card" :class="{selected:selected.has(device.deviceId)}"><div class="cardtop"><label><input type="checkbox" :checked="selected.has(device.deviceId)" @change="toggleSelection(device.deviceId,$event.target.checked)"><span class="device-id" :title="device.deviceId">{{ device.deviceId }}</span></label><span class="pill" :class="{off:!device.online}">{{ device.online?'● 在线':'○ 离线' }}</span></div><div class="roomno">{{ device.snapshot?.number||'—' }}</div><div class="roomtitle">{{ device.snapshot?.name||'等待首次同步' }}</div><div class="state" :style="{color:currentState(device).color}"><i>{{ currentState(device).icon }}</i>{{ currentState(device).name }}</div><small :class="{'chip-pending':device.pending}">{{ device.pending?'等待设备确认…':device.online?'设备已确认':'最后已知状态' }}</small><small>{{ formatTime(device.lastSeen) }}</small><div class="cardactions"><button :disabled="!usable(device)" @click="openSwitch(device)">{{ device.pending?'等待确认':'切换状态' }}</button><button :disabled="!device.snapshot" @click="editDevice(device)">管理</button></div></article></div>
 <div v-else class="tablebox"><table><thead><tr><th>选择</th><th>房间</th><th>设备编号</th><th>连接</th><th>状态</th><th>最近同步</th><th>操作</th></tr></thead><tbody><tr v-for="device in visibleDevices" :key="device.deviceId"><td><input type="checkbox" :checked="selected.has(device.deviceId)" @change="toggleSelection(device.deviceId,$event.target.checked)"></td><td>{{ device.snapshot?.number||'—' }} · {{ device.snapshot?.name||'等待同步' }}</td><td><span class="device-id" :title="device.deviceId">{{ device.deviceId }}</span></td><td>{{ device.online?'在线':'离线' }}</td><td :style="{color:currentState(device).color}">{{ device.online?'':'最后已知：' }}{{ currentState(device).name }}</td><td>{{ device.pending?'等待确认':formatTime(device.lastSeen) }}</td><td><button :disabled="!usable(device)" @click="openSwitch(device)">切换状态</button> <button :disabled="!device.snapshot" @click="editDevice(device)">管理</button></td></tr></tbody></table></div>
 <div class="paging"><span>每页 {{ pageSize }} 台 · 选择可跨页保留</span><div><button :disabled="pageNo<=1" @click="pageNo--">上一页</button><span>{{ pageNo }} / {{ pageCount }}</span><button :disabled="pageNo>=pageCount" @click="pageNo++">下一页</button></div></div>
 </template>
 <template v-if="page==='templates'"><div class="tools page-tools"><span class="muted">模板保存不会自动修改设备，需明确下发目标与当前状态。</span><span class="spacer"></span><button class="primary" :disabled="!!loadError" @click="editTemplate()">＋ 新建模板</button></div><div v-if="!templates.length" class="empty">还没有状态模板，点击“新建模板”添加。</div><div class="templates"><article v-for="template in templates" :key="template.id" class="template"><div class="eyebrow">状态配置模板</div><h2>{{ template.name }}</h2><div class="chips"><span v-for="state in template.states" :key="state.id" :style="{color:state.color}">{{ state.icon }} {{ state.name }}</span></div><p class="muted">{{ template.states.length }} 个状态 · 手动切换</p><div class="actions"><button class="flat button-danger" :disabled="!!loadError" @click="requestDelete(template)">删除</button><button :disabled="!!loadError" @click="editTemplate(template)">编辑</button><button class="primary" :disabled="!!loadError" @click="openDeploy(template)">选择设备并下发</button></div></article></div></template>
 <template v-if="page==='logs'"><div class="tools page-tools"><span class="muted">最近操作优先 · 结果来自设备确认</span><span class="spacer"></span><button :disabled="!logs.length" @click="exportLogs">导出记录</button></div><div v-if="!logs.length" class="empty">还没有操作记录。远程切换状态或下发配置后可在这里查看执行结果。</div><div v-else class="tablebox"><table><thead><tr><th>提交时间</th><th>设备</th><th>目标房间 / 状态</th><th>结果</th><th>说明</th></tr></thead><tbody><tr v-for="record in logs" :key="record.id"><td>{{ formatTime(record.createdAt) }}</td><td><span class="device-id" :title="record.deviceId">{{ record.deviceId }}</span></td><td>{{ record.snapshot?.number||'—' }} / {{ record.snapshot?.states?.find(s=>s.id===record.snapshot.current)?.name||'—' }}</td><td><span class="status-badge" :class="record.status">{{ statusLabels[record.status]||record.status }}</span></td><td class="wrap-cell">{{ record.message||'—' }}</td></tr></tbody></table></div></template>
 <template v-if="page==='settings'"><div v-if="desktopBridge" class="settingpanel page-tools"><div class="desktop-panel-heading"><div><div class="eyebrow">WINDOWS 本机运行</div><h3>管理电脑</h3></div><span class="pill">服务随程序运行</span></div><p class="muted">关闭窗口会收至托盘，设备仍可连接；从托盘退出程序时停止连接。</p><dl class="desktop-details"><div><dt>设备连接地址</dt><dd><span v-for="address in desktopAddresses" :key="address" class="address-value">{{ address }}</span><span v-if="!desktopAddresses.length">未检测到局域网地址，请连接网络后点击刷新。</span></dd></div><div><dt>通信端口</dt><dd>{{ desktopInfo?.port||'—' }}</dd></div><div><dt>数据目录</dt><dd class="device-id-full">{{ desktopInfo?.dataDir||'正在读取…' }}</dd></div><div><dt>程序版本</dt><dd>{{ desktopInfo?.version||'—' }}</dd></div></dl><p class="hint">多网卡电脑请选用与安卓设备在同一网络的地址。安卓端仍使用原有“服务器地址”输入框，无需更新 APK。</p><div class="desktop-actions"><button @click="loadDesktopInfo" :disabled="backupBusy">刷新地址</button><button @click="openDataDirectory" :disabled="backupBusy">打开数据目录</button><button class="primary" @click="openModal('backup')" :disabled="backupBusy">{{ backupBusy?'正在备份…':'备份数据' }}</button></div><p v-if="backupPath" class="notice device-id-full">已备份至 {{ backupPath }}</p><p class="error" role="alert">{{ desktopError }}</p></div><div class="settingpanel page-tools"><h3>管理员账户</h3><p class="muted">{{ username }} · 可管理全部设备</p><div class="notice">修改密码后需要重新登录。电脑管理密码与安卓设备本地管理密码相互独立。</div><form @submit.prevent="changePassword"><div class="password-grid"><label>当前密码<input v-model="oldPassword" type="password" autocomplete="current-password" required></label><label>新密码<input v-model="newPassword" type="password" autocomplete="new-password" minlength="8" maxlength="128" required></label><label>确认新密码<input v-model="confirmPassword" type="password" autocomplete="new-password" minlength="8" maxlength="128" required></label></div><p class="error" role="alert">{{ passwordError }}</p><button class="primary" :disabled="busy||!!loadError">{{ busy?'正在保存…':'修改密码' }}</button></form><div class="section"><h3>设备接入</h3><p class="muted">在安卓端原有“服务器地址”输入框填写管理电脑地址，再使用下方注册密钥注册。设备仍可独立运行，也可接收远程指令。</p><div class="notice">设备注册密钥：<strong class="device-id-full">{{ enrollmentKey||'—' }}</strong><br>仅在设备首次注册时使用；更换后旧密钥立即失效，已注册设备不受影响。</div><form @submit.prevent="changeEnrollmentKey"><label>更换注册密钥<input v-model="newEnrollmentKey" autocomplete="off" minlength="12" maxlength="255" placeholder="输入至少12字符的新密钥"></label><p class="error" role="alert">{{ keyError }}</p><button class="primary" :disabled="keyBusy||!!loadError">{{ keyBusy?'正在保存…':'保存新密钥' }}</button></form><button @click="openModal('enroll')">查看接入说明</button></div><div class="section"><h3>同步原则</h3><p class="muted">收到设备确认后才显示生效。离线不排队下发。设备本地数据版本变化时，旧指令会报告版本冲突，请刷新后重新操作。</p></div></div></template>
 </main>
 </template>
 <div v-if="modal" class="modal-overlay" @click.self="closeModal"><section class="modal-box" role="dialog" aria-modal="true" aria-labelledby="modal-heading"><div class="dialoghead"><h2 id="modal-heading">{{ {switch:'切换房间状态',device:'设备与房间设置',template:draft?.id?'编辑状态模板':'新建状态模板',deploy:'下发状态模板',delete:'删除状态模板',enroll:'接入安卓设备',backup:'备份本机数据'}[modal] }}</h2><button :disabled="busy" aria-label="关闭弹窗" @click="closeModal">✕</button></div>
 <template v-if="modal==='enroll'"><p>1. 保持此管理程序运行，确认安卓设备与管理电脑在同一网络。</p><p>2. 在安卓端长按房间名称，验证本机管理员密码后进入设置，选择联网模式。</p><p>3. 在原有“服务器地址”中填写下方管理电脑地址，输入注册密钥，然后注册并开启同步。</p><div v-if="desktopBridge" class="notice"><strong>管理电脑连接地址</strong><span v-for="address in desktopAddresses" :key="address" class="address-value">{{ address }}</span><p v-if="!desktopAddresses.length">未检测到局域网地址，请确认电脑已连接网络。</p><p>通信端口：{{ desktopInfo?.port||'—' }}</p><button class="flat" @click="loadDesktopInfo">刷新地址</button></div><div v-else class="notice">当前管理地址：<strong class="device-id-full">{{ connectionOrigin }}</strong><br>设备应填写管理电脑的局域网 IP 或域名，不能填写设备自身的 localhost。</div><p class="muted">若显示多个地址，请选择与安卓设备在同一网络的地址；Windows 防火墙首次提示时允许此程序在专用网络通信。</p><p class="muted">注册密钥在「系统设置 · 设备接入」查看或更换。不要把电脑管理密码当作注册密钥。</p><div class="notice">设备首次同步后显示真实房间资料。设备唯一编号由安卓端生成，无需手工填写，也无需更新现有 APK。</div></template>
 <template v-if="modal==='backup'"><p>备份房间、设备、状态模板、操作记录和管理配置。</p><div class="notice">备份时会短暂停止设备同步，完成后自动恢复。期间安卓设备仍可独立操作。请妥善保管备份文件，其中包含设备凭据。</div><div class="actions"><button @click="closeModal">取消</button><button class="primary" @click="closeModal();backupData()">选择位置并备份</button></div></template>
 <template v-if="modal==='switch'"><p class="muted">{{ activeDevice.snapshot.number }} · {{ activeDevice.snapshot.name }}</p><div class="notice">指令提交后等待设备确认。若设备本地数据已变化，将报告版本冲突，不覆盖本地新数据。</div><div class="choices"><button v-for="state in activeDevice.snapshot.states" :key="state.id" :disabled="busy||state.id===activeDevice.snapshot.current" @click="changeState(state.id)"><span :style="{color:state.color}">{{ state.icon }}</span>{{ state.name }}<span>{{ state.id===activeDevice.snapshot.current?'当前状态':busy?'正在提交…':'选择' }}</span></button></div></template>
 <form v-if="modal==='device'" @submit.prevent="saveDevice"><p class="muted device-id-full">设备编号 {{ activeDevice.deviceId }}</p><div class="fields"><label>房间号<input v-model="draft.number" maxlength="12" required :disabled="!activeDevice.online||busy"></label><label>房间名称<input v-model="draft.name" maxlength="24" required :disabled="!activeDevice.online||busy"></label></div><div class="notice">{{ activeDevice.online?'修改需要设备确认后生效，设备本地编辑能力不受影响。':'当前设备离线，仅可查看最后已知信息。恢复在线后请关闭弹窗并重新打开。' }}</div><h3>本机状态配置</h3><div class="chips"><span v-for="state in draft.states" :key="state.id" :style="{color:state.color}">{{ state.icon }} {{ state.name }}</span></div><p class="muted">通过状态模板可替换设备的状态目录，也可以直接在安卓设备上编辑。</p><div class="actions"><button type="button" :disabled="busy" @click="closeModal">取消</button><button class="primary" :disabled="busy||!usable(activeDevice)">{{ busy?'正在提交…':'保存并下发' }}</button></div></form>
 <form v-if="modal==='template'" @submit.prevent="saveTemplate"><label class="form-label">模板名称<input v-model="draft.name" maxlength="40" required :disabled="busy"></label><div class="notice">状态名称、颜色、图标可自定义。保存模板不会立即修改设备。</div><div v-for="(state,index) in draft.states" :key="state.id" class="staterow"><input v-model="state.name" aria-label="状态名称" maxlength="16" required :disabled="busy"><input v-model="state.color" type="color" aria-label="状态颜色" :disabled="busy"><select v-model="state.icon" aria-label="状态图标" :disabled="busy"><option v-for="icon in icons" :key="icon">{{ icon }}</option></select><button type="button" :disabled="busy||draft.states.length===1" @click="removeState(index)">删除</button></div><button type="button" :disabled="busy||draft.states.length>=32" @click="draft.states.push(newState())">＋ 添加状态</button><div class="actions"><button type="button" :disabled="busy" @click="closeModal">取消</button><button class="primary" :disabled="busy">{{ busy?'正在保存…':'保存模板' }}</button></div></form>
 <template v-if="modal==='delete'"><p>确定删除模板“{{ draft.name }}”吗？</p><p class="muted">删除后不能撤销，已下发到设备的状态配置不受影响。</p><div class="actions"><button :disabled="busy" @click="closeModal">取消</button><button class="button-danger" :disabled="busy" @click="deleteTemplate">确认删除</button></div></template>
 <form v-if="modal==='deploy'" @submit.prevent="deploy"><div class="fields"><label>状态模板<select v-model="templateId" :disabled="busy||batchResults.length"><option v-for="template in templates" :key="template.id" :value="template.id">{{ template.name }}</option></select></label><label>下发后当前状态<select v-model="afterState" :disabled="busy||batchResults.length"><option v-for="state in chosenTemplate?.states||[]" :key="state.id" :value="state.id">{{ state.name }}</option></select></label></div><div class="notice">将替换所选设备的状态目录，并把当前状态设为上述选项。离线和正在等待确认的设备不可操作，不保留旧指令。</div><div class="checklist"><label v-for="device in devices" :key="device.deviceId"><input type="checkbox" :checked="targetIds.includes(device.deviceId)" :disabled="!usable(device)||busy||batchResults.length" @change="toggleTarget(device.deviceId,$event.target.checked)">{{ device.snapshot?.number||'—' }} · {{ device.snapshot?.name||'等待同步' }}<span class="muted">{{ device.pending?'等待确认':device.online?'在线':'离线 · 跳过' }}</span></label></div><p v-if="!devices.length" class="muted">尚无设备接入。</p><div v-if="batchResults.length" class="batch-result notice"><p v-for="result in batchResults" :key="result.id" :class="{warning:!result.ok}"><span class="device-id" :title="result.id">{{ result.id }}</span>：{{ result.message }}</p><p>提交成功不等于执行成功，请在操作记录查看设备确认结果。</p></div><div class="actions"><button type="button" :disabled="busy" @click="closeModal">{{ batchResults.length?'完成':'取消' }}</button><button v-if="!batchResults.length" class="primary" :disabled="busy||!targetIds.length||!!loadError">{{ busy?'正在逐台提交…':`确认下发至 ${targetIds.length} 台设备` }}</button></div></form>
 <p class="error" role="alert">{{ modalError }}</p>
 </section></div><div v-if="toast" class="toast" role="status">{{ toast }}</div>
</template>
